#!/bin/bash
# Run a switch testbench for the tt / ss / ff corners (each file loops over the temperatures itself).
#
# usage: ./run_corners.sh <netlist generated by xschem (.spice)> <testbench file (.spice)>
# example: ./run_corners.sh /foss/designs/TG_sw.spice /foss/designs/tb_switch_tg.spice
#
# For each corner the script
#   1. copies the testbench with the corner name swapped in the include lines and in the file names (CORNER),
#   2. copies the netlist with its .include line pointing to that copy,
#   3. runs ngspice in batch mode.
# The original files are not modified. Results: /foss/designs/ron_*_<corner>_<m40|27|85|125>.txt (m40 = -40 C)

NET=$1
TB=$2
TBNAME=$(basename "$TB")
TMP=${TMPDIR:-/tmp}

for c in tt ss ff; do
  tb_c="$TMP/${TBNAME%.spice}_$c.spice"
  net_c="$TMP/$(basename "${NET%.spice}")_$c.spice"
  # corner in include lines (works for both tt and ss defaults) and in output names
  sed -e "s#corners/tt#corners/$c#g" -e "s#corners/ss#corners/$c#g" -e "s#CORNER#$c#g" "$TB" > "$tb_c"
  sed -e "s#$TBNAME#$(basename "$tb_c")#g" -e "s#/foss/designs/$(basename "$tb_c")#$tb_c#g" "$NET" > "$net_c"
  echo "== corner $c =="
  ngspice -b "$net_c" -o "$TMP/run_$c.log"
done
